import {
  encodeDeployData,
  encodeFunctionData,
  getAddress,
  getContractAddress,
  keccak256,
  parseAbi,
  stringToHex,
  type Address,
  type Hex,
} from "viem";

import {
  SINGLETON_FACTORY_ADDRESS,
  singletonFactoryAbi,
} from "./standing-order-batch-executor.js";

export const MEGA_RIP_KEEPER_EXECUTOR_SALT = keccak256(
  stringToHex("pull-pool-keeper/MegaRipKeeperExecutor/v1"),
);
export const MEGA_RIP_KEEPER_EXECUTOR_DEPLOY_GAS_LIMIT = 600_000n;
export const MEGA_RIP_KEEPER_EXECUTOR_MAX_CALLS = 64n;

export const megaRipKeeperExecutorAbi = parseAbi([
  "constructor(address owner)",
  "function MAX_CALLS() view returns (uint256)",
  "function MEGA_RIP() view returns (address)",
  "function owner() view returns (address)",
  "function pullExact(uint256 maxPulls,uint256 minimumBounty) returns (uint256 bounty)",
  "function settleExact(uint256[] listingIds,uint256 minimumBounty) returns (uint256 bounty)",
  "function syncStuckExact(uint256[] listingIds,uint256 minimumBounty) returns (uint256 bounty)",
  "event RewardedExecution(bytes4 indexed selector,uint256 calls,uint256 bounty)",
  "error EmptyBatch()",
  "error InvalidOwner()",
  "error PaymentFailed()",
  "error TooManyCalls()",
  "error Unauthorized()",
  "error UnauthorizedPayment()",
  "error UnexpectedBounty(uint256 actual,uint256 minimum)",
]);

// Generated from solc 0.8.28, Cancun, optimizer enabled with 1,000,000 runs.
export const MEGA_RIP_KEEPER_EXECUTOR_BYTECODE = "" as Hex;
const MEGA_RIP_KEEPER_EXECUTOR_RUNTIME_TEMPLATE = "" as Hex;
const OWNER_IMMUTABLE_OFFSETS = [364, 1335, 1521] as const;

function patchOwnerImmutable(template: Hex, owner: Address): Hex {
  const ownerWord = owner.slice(2).padStart(64, "0");
  let body = template.slice(2);
  for (const offset of OWNER_IMMUTABLE_OFFSETS) {
    const start = offset * 2;
    body = `${body.slice(0, start)}${ownerWord}${body.slice(start + 64)}`;
  }
  return `0x${body}`;
}
export function megaRipKeeperExecutorDeployment(owner: Address): {
  readonly initCode: Hex;
  readonly address: Address;
  readonly expectedRuntimeCode: Hex;
  readonly expectedRuntimeCodeHash: Hex;
  readonly deployData: Hex;
} {
  const canonicalOwner = getAddress(owner);
  const initCode = encodeDeployData({
    abi: megaRipKeeperExecutorAbi,
    bytecode: MEGA_RIP_KEEPER_EXECUTOR_BYTECODE,
    args: [canonicalOwner],
  });
  const address = getContractAddress({
    from: SINGLETON_FACTORY_ADDRESS,
    opcode: "CREATE2",
    salt: MEGA_RIP_KEEPER_EXECUTOR_SALT,
    bytecode: initCode,
  });
  const expectedRuntimeCode = patchOwnerImmutable(
    MEGA_RIP_KEEPER_EXECUTOR_RUNTIME_TEMPLATE,
    canonicalOwner,
  );
  return {
    initCode,
    address,
    expectedRuntimeCode,
    expectedRuntimeCodeHash: keccak256(expectedRuntimeCode),
    deployData: encodeFunctionData({
      abi: singletonFactoryAbi,
      functionName: "deploy",
      args: [initCode, MEGA_RIP_KEEPER_EXECUTOR_SALT],
    }),
  };
}

export function encodeMegaRipExactPull(
  maxPulls: bigint,
  minimumBounty: bigint,
): Hex {
  if (
    maxPulls <= 0n ||
    maxPulls > MEGA_RIP_KEEPER_EXECUTOR_MAX_CALLS ||
    minimumBounty <= 0n
  ) {
    throw new Error("invalid exact MegaRip pull bounds");
  }
  return encodeFunctionData({
    abi: megaRipKeeperExecutorAbi,
    functionName: "pullExact",
    args: [maxPulls, minimumBounty],
  });
}

export function encodeMegaRipExactSettlements(
  listingIds: readonly bigint[],
  minimumBounty: bigint,
): Hex {
  return encodeMegaRipExactListings("settleExact", listingIds, minimumBounty);
}

export function encodeMegaRipExactRecoveries(
  listingIds: readonly bigint[],
  minimumBounty: bigint,
): Hex {
  return encodeMegaRipExactListings("syncStuckExact", listingIds, minimumBounty);
}

function encodeMegaRipExactListings(
  functionName: "settleExact" | "syncStuckExact",
  listingIds: readonly bigint[],
  minimumBounty: bigint,
): Hex {
  if (
    listingIds.length === 0 ||
    BigInt(listingIds.length) > MEGA_RIP_KEEPER_EXECUTOR_MAX_CALLS ||
    minimumBounty <= 0n
  ) {
    throw new Error("invalid exact MegaRip listing batch");
  }
  return encodeFunctionData({
    abi: megaRipKeeperExecutorAbi,
    functionName,
    args: [[...listingIds], minimumBounty],
  });
}
